package rpg.engine.script.runtime;
import rpg.engine.script.*;import static rpg.engine.script.Ast.*;import java.util.*;
public final class ScriptEngine {private final ScriptHost host;public ScriptEngine(ScriptHost h){host=h;}public Object execute(String source){return execute(new Parser(source).parse());}public Object execute(Block b){var e=new Env();try{run(b,e);}catch(ReturnSignal r){return r.value;}return null;}private void run(Stmt s,Env e){if(s instanceof Block b){for(var x:b.body())run(x,e);}else if(s instanceof Let x)e.v.put(x.name(),eval(x.value(),e));else if(s instanceof Assign x)e.v.put(x.name(),eval(x.value(),e));else if(s instanceof ExprStmt x)eval(x.expr(),e);else if(s instanceof Return x)throw new ReturnSignal(eval(x.value(),e));else if(s instanceof If x)run(truth(eval(x.test(),e))?x.yes():x.no(),e);}private Object eval(Expr x,Env e){if(x instanceof Literal l)return l.value();if(x instanceof Variable v){if(e.v.containsKey(v.name()))return e.v.get(v.name());Object g=host.global(v.name());if(g!=null)return g;return new FunctionRef(v.name());}if(x instanceof Member m){Object o=eval(m.target(),e);if(o instanceof Map<?,?> map)return map.get(m.name());throw new IllegalArgumentException("not an object: "+m.name());}if(x instanceof Call c){Object target=eval(c.target(),e);var a=c.args().stream().map(z->eval(z,e)).toList();if(target instanceof FunctionRef f)return host.call(f.name,a);throw new IllegalArgumentException("not callable");}if(x instanceof Unary u){double n=num(eval(u.x(),e));return -n;}if(x instanceof Binary b){Object l=eval(b.a(),e),r=eval(b.b(),e);return bin(b.op(),l,r);}throw new IllegalStateException();}private Object bin(String o,Object a,Object b){if(o.equals("+")&&(a instanceof String||b instanceof String))return String.valueOf(a)+b;double x=num(a),y=num(b);return switch(o){case"+"->x+y;case"-"->x-y;case"*"->x*y;case"/"->x/y;case"lt"->x<y;case"gt"->x>y;case"le"->x<=y;case"ge"->x>=y;case"=="->Objects.equals(a,b);case"!="->!Objects.equals(a,b);default->throw new IllegalArgumentException("operator "+o);};}private static double num(Object x){if(x instanceof Number n)return n.doubleValue();throw new IllegalArgumentException("number expected, got "+x);}private static boolean truth(Object x){return x!=null&&!Boolean.FALSE.equals(x)&&(!(x instanceof Number n)||n.doubleValue()!=0);}private static final class Env{final Map<String,Object>v=new HashMap<>();}private record FunctionRef(String name){}private static final class ReturnSignal extends RuntimeException{final Object value;ReturnSignal(Object v){this.value=v;}}
}
